create extension if not exists pgcrypto;
create type public.role_user as enum ('GURU','SISWA');
create type public.status_absensi as enum ('HADIR','SAKIT','IZIN','LAINNYA','ALPA');
create table public.kelas(id uuid primary key default gen_random_uuid(), nama text not null unique, created_at timestamptz default now());
create table public.users(id uuid primary key references auth.users(id) on delete cascade,nama text not null,email text not null unique,role role_user not null,kelas_id uuid references kelas(id),nis text unique,created_at timestamptz default now(),constraint siswa_nis check((role='SISWA' and nis is not null) or role='GURU'));
create table public.guru(id uuid primary key references users(id) on delete cascade,kelas_id uuid not null references kelas(id));
create table public.siswa(id uuid primary key references users(id) on delete cascade,kelas_id uuid not null references kelas(id),nis text not null unique);
create table public.absensi(id uuid primary key default gen_random_uuid(),tanggal date not null,siswa_id uuid not null references siswa(id) on delete cascade,status status_absensi not null,jam_scan time,alasan text,foto_surat text,keterangan text,disetujui boolean,dibuat_pada timestamptz default now(),unique(siswa_id,tanggal));
create table public.qr_token(tanggal date primary key,token uuid not null unique,expired_at timestamptz not null,created_at timestamptz default now());
create table public.jadwal_pelajaran(id uuid primary key default gen_random_uuid(),kelas_id uuid not null references kelas(id) on delete cascade,hari text not null check(hari in('SENIN','SELASA','RABU','KAMIS','JUMAT','SABTU')),jam_mulai time not null,jam_selesai time not null,mapel text not null,guru_mapel text not null);
create table public.jadwal_piket(id uuid primary key default gen_random_uuid(),kelas_id uuid not null references kelas(id) on delete cascade,siswa_id uuid not null references siswa(id) on delete cascade,hari text not null check(hari in('SENIN','SELASA','RABU','KAMIS','JUMAT','SABTU')),unique(siswa_id,hari));
create table public.tugas(id uuid primary key default gen_random_uuid(),kelas_id uuid not null references kelas(id) on delete cascade,judul text not null,mapel text not null,deskripsi text not null,deadline timestamptz not null,created_at timestamptz default now());
create or replace function public.my_role() returns role_user language sql stable security definer set search_path=public as $$select role from users where id=auth.uid()$$;
create or replace function public.my_class() returns uuid language sql stable security definer set search_path=public as $$select kelas_id from users where id=auth.uid()$$;
create or replace function public.daily_qr_token() returns json language plpgsql security definer set search_path=public as $$declare d date:=(now() at time zone 'Asia/Jakarta')::date; exp timestamptz:=((now() at time zone 'Asia/Jakarta')::date+time '07:00') at time zone 'Asia/Jakarta';r qr_token;begin if now()>=exp then raise exception 'QR sudah kedaluwarsa';end if;insert into qr_token(tanggal,token,expired_at)values(d,gen_random_uuid(),exp)on conflict(tanggal)do update set token=qr_token.token returning * into r;return json_build_object('token',r.token,'expired_at',r.expired_at);end $$;
alter table kelas enable row level security;alter table users enable row level security;alter table guru enable row level security;alter table siswa enable row level security;alter table absensi enable row level security;alter table qr_token enable row level security;alter table jadwal_pelajaran enable row level security;alter table jadwal_piket enable row level security;alter table tugas enable row level security;
create policy "class users" on users for select using(kelas_id=my_class() or id=auth.uid());create policy "student rows" on siswa for select using(kelas_id=my_class());create policy "schedule read" on jadwal_pelajaran for select using(kelas_id=my_class());create policy "schedule teacher" on jadwal_pelajaran for all using(my_role()='GURU' and kelas_id=my_class())with check(my_role()='GURU' and kelas_id=my_class());create policy "duty read" on jadwal_piket for select using(kelas_id=my_class());create policy "duty teacher" on jadwal_piket for all using(my_role()='GURU' and kelas_id=my_class())with check(my_role()='GURU' and kelas_id=my_class());create policy "task read" on tugas for select using(kelas_id=my_class());create policy "task teacher" on tugas for all using(my_role()='GURU' and kelas_id=my_class())with check(my_role()='GURU' and kelas_id=my_class());create policy "own attendance" on absensi for select using(siswa_id=auth.uid());create policy "teacher attendance" on absensi for all using(my_role()='GURU' and exists(select 1 from siswa s where s.id=absensi.siswa_id and s.kelas_id=my_class()))with check(my_role()='GURU');
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('surat','surat',false,2097152,array['image/jpeg','image/png'])on conflict(id)do nothing;create policy "own upload" on storage.objects for insert to authenticated with check(bucket_id='surat' and(storage.foldername(name))[1]=auth.uid()::text);create policy "letter read" on storage.objects for select to authenticated using(bucket_id='surat' and((storage.foldername(name))[1]=auth.uid()::text or my_role()='GURU'));
